const bundle = JSON.parse(Buffer.from(PAYLOAD, 'base64').toString('utf8'));

function place(rel, buf) {
  const target = path.join(root, rel);
  if (fs.existsSync(target)) fs.copyFileSync(target, target + '.before-favicon');
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, buf);
  console.log('  [ok] ' + rel);
}

for (const [rel, c] of Object.entries(bundle.text))   place(rel, Buffer.from(c, 'utf8'));
for (const [rel, c] of Object.entries(bundle.binary)) place(rel, Buffer.from(c, 'base64'));

console.log('\n  Favicon installé.\n');
